include!("support/mapping-probes.rs");
#[path="../src/dualray.rs"] mod dualray;
#[path="../src/dualray_config.rs"] mod dualray_config;
use std::hint::black_box;
fn run<G: dualray::DualrayData>() {
 let [lo,hi]=dualray_config::config(G::ID).fold.unwrap();
 let mut map=dualray::Dualray::<G>::new();
 for fold in [false,true] {for interior in [true,false] {
  let inputs:Vec<_>=(0..4096).map(|i| {let l=0.1+0.8*((i as f64*0.7548776662466927)%1.0);[l,if interior {0.01*l}else{0.6},lo+(hi-lo)*(i as f64+0.37)/4096.0+if fold {0.0}else{15.0}]}).collect();
  let mut out=[0.;3];let mut sink=0.;let mut passes=Vec::new();
  for i in 0..75 {let start=std::time::Instant::now();let mut sum=0.;for input in &inputs {map.map(black_box(input),&mut out);sum+=out[0]+out[1]+out[2];}sink+=black_box(sum);if i>=50 {passes.push(start.elapsed().as_nanos() as f64/inputs.len() as f64);}}
  println!("{{\"gamut\":\"{}\",\"workload\":\"{}-{}\",\"checksum\":{},\"passes\":{:?}}}",G::DEFINITION.name,if fold {"fold"}else{"ordinary"},if interior {"interior"}else{"mapped"},sink,passes);
 }}
}
fn main(){match std::env::args().nth(1).as_deref(){Some("srgb")=>run::<gamut::Srgb>(),Some("rec2020")=>run::<gamut::Rec2020>(),_=>panic!("gamut required")}}

